import { t, section } from './types';

/**
 * Mobile app test matrix, derived from trainistan_app/lib.
 *
 * Routes come from lib/core/router/app_router.dart, tab layouts from
 * lib/features/shell, and screens from lib/features/*\/presentation. The app
 * uses Riverpod, go_router with an auth redirect, Dio against the same API,
 * flutter_secure_storage for tokens, socket_io_client for chat presence,
 * Agora for live sessions, chewie/video_player for playback, file_picker for
 * uploads and Firebase for push.
 *
 * These are not generic mobile checks. Every case below points at something
 * that exists in that source tree.
 */

